class Thermostat {
  target = 20;

  constructor(room) {
    this.room = room;
  }

  up(step) {
    if (this.target + step > 30) {
      return false;
    }
    this.target += step;
    return true;
  }

  down(step) {
    if (this.target - step < 10) {
      return false;
    }
    this.target -= step;
    return true;
  }
}

function report(thermostat, action, ok) {
  console.log(`${thermostat.room} ${action}: ${ok ? "ok" : "refused"}, target ${thermostat.target}`);
}

const hall = new Thermostat("Hall");
const office = new Thermostat("Office");

report(hall, "up 5", hall.up(5));
report(hall, "up 8", hall.up(8));
report(hall, "down 3", hall.down(3));
report(office, "down 12", office.down(12));
report(office, "down 10", office.down(10));
console.log(`Hall is ${hall.target}, Office is ${office.target}`);

steps.body:
Put an instance in a template literal and you get `[object Object]`. Give the class a `toString()` method and both `${book}` and `String(book)` use it instead:

```javascript
class Book {
  constructor(title, year) {
    this.title = title;
    this.year = year;
  }

  toString() {
    return `${this.title} (${this.year})`;
  }
}

const book = new Book("Dune", 1965);
console.log(`${book}`); // Dune (1965)
console.log(String(book)); // Dune (1965)
```

`console.log(book)` on its own ignores `toString` and prints Node's debug view, such as `Book { title: 'Dune', year: 1965 }`. Always print instances through a template literal or a method.

Instances are ordinary values, so they live happily in arrays and every array method works on them. Callbacks receive whole instances and can read fields or call methods:

```javascript
const recent = shelf.filter((book) => book.year > 1960);
const titles = shelf.map((book) => book.title).join(", ");
const byYear = shelf.toSorted((a, b) => a.year - b.year);
```

`sort` reorders the array in place, while `toSorted` returns a sorted copy and leaves the original alone. Build the array after the class declaration, because classes are not hoisted.

example.code:
class Book {
  constructor(title, author, year) {
    this.title = title;
    this.author = author;
    this.year = year;
  }

  toString() {
    return `${this.title} by ${this.author} (${this.year})`;
  }
}

const shelf = [
  new Book("Dune", "Frank Herbert", 1965),
  new Book("The Hobbit", "J.R.R. Tolkien", 1937),
  new Book("Neuromancer", "William Gibson", 1984),
  new Book("1984", "George Orwell", 1949),
];

const byYear = shelf.toSorted((a, b) => a.year - b.year);
for (const book of byYear) {
  console.log(`${book}`);
}

const older = byYear.filter((book) => book.year < 1950).map((book) => book.title);
console.log(`Before 1950: ${older.join(", ")}`);

