practice.solution:
class Player {
  constructor(name, score) {
    this.name = name;
    this.score = score;
  }

  toString() {
    return `${this.name}: ${this.score} pts`;
  }
}

const team = [
  new Player("Ana", 72),
  new Player("Ben", 45),
  new Player("Cai", 88),
  new Player("Dev", 50),
  new Player("Eli", 61),
];

const top = team.filter((player) => player.score > 50).sort((a, b) => b.score - a.score);
for (const player of top) {
  console.log(`${player}`);
}

const others = team.filter((player) => player.score <= 50);
console.log(`Others: ${others.map((player) => player.name).join(", ")}`);
